/* Token Launch Radar -- dashboard stylesheet.
 *
 * A pale green-grey page, white panels, dark green-black ink. Numbers are
 * set in a monospace stack so TVL, growth and implied value line up down
 * the board. Nothing here fetches anything: the page is static.
 */

:root {
  --bg: #f2f5f3;
  --panel: #ffffff;
  --ink: #16211c;
  --muted: #5f6f67;
  --accent: #0f7a5a;
  --neg: #b23b2e;
  --line: #d8e2dc;
  --font-body: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-num: ui-monospace, "SF Mono", "DejaVu Sans Mono", "Liberation Mono", Menlo, Consolas, monospace;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.5;
}

/* The skip link sits far off screen until keyboard focus lands on it. */
.skip {
  position: absolute;
  left: -9999px;
  top: 8px;
  z-index: 20;
  padding: 10px 16px;
  border-radius: 8px;
  background: var(--ink);
  color: #fff;
  font-size: 14px;
  text-decoration: none;
}

.skip:focus {
  left: 8px;
}

.shell {
  max-width: 1320px;
  margin: 0 auto;
  padding: 24px 32px 48px;
}

/* --- header ---------------------------------------------------------- */

.top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding: 0 0 17px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.mark {
  display: inline-block;
  flex: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
